	"mlforge/internal/checkpoint"
	"mlforge/internal/logparser"
	"mlforge/internal/types"
)

type ArtifactPaths struct {
	Checkpoints []string
	Logs        []string
	Configs     []string
}

func DiscoverArtifacts(dir string) (ArtifactPaths, error) {
	var ap ArtifactPaths
	err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		name := d.Name()
		lower := strings.ToLower(name)
		switch {
		case strings.HasSuffix(lower, ".mlck"):
			ap.Checkpoints = append(ap.Checkpoints, path)
		case strings.HasSuffix(lower, ".jsonl"):
			ap.Logs = append(ap.Logs, path)
		case strings.HasPrefix(name, "config_") && strings.HasSuffix(lower, ".json"):
			ap.Configs = append(ap.Configs, path)
		}
		return nil
	})
	if err != nil {
		return ap, err
	}
	sort.Strings(ap.Checkpoints)
	sort.Strings(ap.Logs)
	sort.Strings(ap.Configs)
	return ap, nil
}

type IngestCheckpoint struct {
	File               string                 `json:"file"`
	FileHash           string                 `json:"file_hash"`
	Version            uint32                 `json:"version"`
	NumTensors         uint32                 `json:"num_tensors"`
	NumMetadata        uint32                 `json:"num_metadata"`
	Signed             bool                   `json:"signed"`
	CreationTimestamp  string                 `json:"creation_timestamp"`
	Provenance         map[string]interface{} `json:"provenance"`
}

type IngestLogShard struct {
	File      string   `json:"file"`
	Entries   int      `json:"entries"`
	StepRange []int    `json:"step_range"`
	EpochRange []int   `json:"epoch_range"`
	TimeRange []string `json:"time_range"`
}

type IngestConfig struct {
	File      string `json:"file"`
	ModelName string `json:"model_name"`
	Dataset   string `json:"dataset"`
}

type IngestOutput struct {
	Status     string           `json:"status"`
	EvidenceDir string          `json:"evidence_dir"`
	Artifacts  struct {
		Checkpoints []IngestCheckpoint `json:"checkpoints"`
		LogShards   []IngestLogShard   `json:"log_shards"`
		Configs     []IngestConfig     `json:"configs"`
	} `json:"artifacts"`
	Totals struct {
		Checkpoints int `json:"checkpoints"`
		LogShards   int `json:"log_shards"`
		Configs     int `json:"configs"`
	} `json:"totals"`
}

func BuildIngest(dir string) (interface{}, error) {
	ap, err := DiscoverArtifacts(dir)
	if err != nil {
		return nil, err
	}
	if len(ap.Checkpoints) == 0 && len(ap.Logs) == 0 && len(ap.Configs) == 0 {
		return nil, fmt.Errorf("no recognizable artifacts found in %s", dir)
	}

	var out IngestOutput
	out.Status = "ok"
	out.EvidenceDir = dir

	for _, p := range ap.Checkpoints {
		cf, err := checkpoint.Parse(p)
		if err != nil || cf == nil {
			continue
		}
		ic := IngestCheckpoint{
			File:       cf.Filename,
			FileHash:   cf.FileHash,
			Version:    cf.Version,
			NumTensors: cf.NumTensors,
			NumMetadata: cf.NumMetadataKeys,
			Signed:     cf.Signed,
			CreationTimestamp: unixToISO(cf.CreationTimestamp),
			Provenance: provenanceToMap(cf.Provenance),
		}
		out.Artifacts.Checkpoints = append(out.Artifacts.Checkpoints, ic)
	}
	sort.Slice(out.Artifacts.Checkpoints, func(i, j int) bool {
		return out.Artifacts.Checkpoints[i].CreationTimestamp < out.Artifacts.Checkpoints[j].CreationTimestamp
	})

	for _, p := range ap.Logs {
		info, entries, err := parseShardRecursive(p)
		if err != nil {
			continue
		}
		shard := IngestLogShard{
			File:    info.File,
			Entries: info.Entries,
		}
		if info.Entries > 0 {
			shard.StepRange = []int{info.MinStep, info.MaxStep}
			shard.EpochRange = []int{info.MinEpoch, info.MaxEpoch}
			if info.MinTs != "" || info.MaxTs != "" {
				shard.TimeRange = []string{info.MinTs, info.MaxTs}
			}
		}
		_ = entries
		out.Artifacts.LogShards = append(out.Artifacts.LogShards, shard)
	}
	sort.Slice(out.Artifacts.LogShards, func(i, j int) bool {
		return out.Artifacts.LogShards[i].File < out.Artifacts.LogShards[j].File
	})

	for _, p := range ap.Configs {
		cfg, err := readConfigSummary(p)
		if err != nil {
			continue
		}
		out.Artifacts.Configs = append(out.Artifacts.Configs, cfg)
	}
	sort.Slice(out.Artifacts.Configs, func(i, j int) bool {
		return out.Artifacts.Configs[i].File < out.Artifacts.Configs[j].File
	})

	out.Totals.Checkpoints = len(out.Artifacts.Checkpoints)
	out.Totals.LogShards = len(out.Artifacts.LogShards)
	out.Totals.Configs = len(out.Artifacts.Configs)
	return out, nil
}

type TimelineGap struct {
	AfterStep  int    `json:"after_step"`
	BeforeStep int    `json:"before_step"`
	Epoch      int    `json:"epoch"`
	GapSteps   int    `json:"gap_steps"`
	AfterTs    string `json:"after_ts"`
	BeforeTs   string `json:"before_ts"`
}

type TimelineOutput struct {
	Status          string             `json:"status"`
	TotalEntries    int                `json:"total_entries"`
	TotalEpochs     int                `json:"total_epochs"`
	StepRange       []int              `json:"step_range"`
	TimeRange       []string           `json:"time_range"`
	ConflictsResolved int              `json:"conflicts_resolved"`
	Gaps            []TimelineGap      `json:"gaps"`
	Entries         []types.TimelineEntry `json:"entries"`
}

func BuildTimeline(dir string) (interface{}, error) {
	entries, shards, err := loadTimelineEntries(dir)
	if err != nil {
		return nil, err
	}
	return buildTimelineFromEntries(entries, shards), nil
}

func buildTimelineFromEntries(entries []types.TimelineEntry, shards []logparser.ShardInfo) TimelineOutput {
	merged, conflicts := mergeTimeline(entries)
	sortTimeline(merged)
	gaps := detectGaps(merged)

	out := TimelineOutput{
		Status:            "ok",
		TotalEntries:      len(merged),
		ConflictsResolved: conflicts,
		Gaps:              gaps,
		Entries:           merged,
	}
	if len(merged) > 0 {
		minStep, maxStep := merged[0].Step, merged[0].Step
		minTs, maxTs := merged[0].Ts, merged[0].Ts
		epochSet := map[int]struct{}{}
		for _, e := range merged {
			epochSet[e.Epoch] = struct{}{}
			if e.Step < minStep {
				minStep = e.Step
			}
			if e.Step > maxStep {
				maxStep = e.Step
			}
			if e.Ts < minTs {
				minTs = e.Ts
			}
			if e.Ts > maxTs {
				maxTs = e.Ts
			}
		}
		out.TotalEpochs = len(epochSet)
		out.StepRange = []int{minStep, maxStep}
		out.TimeRange = []string{minTs, maxTs}
	}
	if out.Gaps == nil {
		out.Gaps = []TimelineGap{}
	}
	if out.Entries == nil {
		out.Entries = []types.TimelineEntry{}
	}
	return out
}

type VerifyCheckpoint struct {
	File                  string   `json:"file"`
	Valid                 bool     `json:"valid"`
	HeaderChecksumValid   bool     `json:"header_checksum_valid"`
	TensorChecksumsValid  bool     `json:"tensor_checksums_valid"`
	SignatureValid        *bool    `json:"signature_valid"`
	ProvenanceValid       bool     `json:"provenance_valid"`
	Issues                []string `json:"issues"`
}

type VerifyOutput struct {
	Status      string            `json:"status"`
	Checkpoints []VerifyCheckpoint `json:"checkpoints"`
	Summary     struct {
		Total   int `json:"total"`
		Valid   int `json:"valid"`
		Invalid int `json:"invalid"
	} `json:"summary"`
}

func BuildVerify(dir string) (interface{}, error) {
	ap, err := DiscoverArtifacts(dir)
	if err != nil {
		return nil, err
	}
	if len(ap.Checkpoints) == 0 {
		return nil, fmt.Errorf("no checkpoint files found")
	}
	var out VerifyOutput
	out.Status = "ok"
	for _, p := range ap.Checkpoints {
		vc := verifyCheckpoint(p)
		out.Checkpoints = append(out.Checkpoints, vc)
	}
	sort.Slice(out.Checkpoints, func(i, j int) bool {
		return out.Checkpoints[i].File < out.Checkpoints[j].File
	})
	out.Summary.Total = len(out.Checkpoints)
	for _, c := range out.Checkpoints {
		if c.Valid {
			out.Summary.Valid++
		} else {
			out.Summary.Invalid++
		}
	}
	return out, nil
}

func verifyCheckpoint(path string) VerifyCheckpoint {
	vc := VerifyCheckpoint{
		File:   filepath.Base(path),
		Issues: []string{},
	}
	cf, err := checkpoint.Parse(path)
	if err != nil || cf == nil {
		vc.HeaderChecksumValid = false
		vc.TensorChecksumsValid = false
		vc.ProvenanceValid = false
		vc.Valid = false
		vc.Issues = append(vc.Issues, fmt.Sprintf("parse_error:%s", err))
		return vc
	}
	vc.HeaderChecksumValid = cf.HeaderValid
	if !cf.HeaderValid {
		vc.Issues = append(vc.Issues, "header_checksum_mismatch")
	}
	vc.TensorChecksumsValid = true
	for _, t := range cf.Tensors {
		if !t.Valid {
			vc.TensorChecksumsValid = false
			vc.Issues = append(vc.Issues, fmt.Sprintf("tensor_checksum_mismatch:%s", t.Name))
		}
	}
	if cf.Signed {
		valid, _ := validateSignature(path)
		vc.SignatureValid = &valid
		if !valid {
			vc.Issues = append(vc.Issues, "signature_invalid")
		}
	}
	vc.ProvenanceValid = validateProvenance(cf)
	if !vc.ProvenanceValid {
		vc.Issues = append(vc.Issues, "provenance_invalid")
	}
	vc.Valid = vc.HeaderChecksumValid && vc.TensorChecksumsValid && vc.ProvenanceValid && (!cf.Signed || (vc.SignatureValid != nil && *vc.SignatureValid))
	return vc
}

func validateSignature(path string) (bool, error) {
	raw, err := os.ReadFile(path)
	if err != nil || len(raw) < 56 {
		return false, err
	}
	sigOff := binary.LittleEndian.Uint64(raw[32:40])
	if sigOff == 0 || int(sigOff) >= len(raw) {
		return false, nil
	}
	if int(sigOff)+5 > len(raw) {
		return false, nil
	}
	off := int(sigOff)
	_ = raw[off] // algorithm
	off++
	signerLen := int(binary.LittleEndian.Uint16(raw[off : off+2]))
	off += 2
	if off+signerLen+2 > len(raw) {
		return false, nil
	}
	signerID := string(raw[off : off+signerLen])
	off += signerLen
	sigLen := int(binary.LittleEndian.Uint16(raw[off : off+2]))
	off += 2
	if off+sigLen > len(raw) {
		return false, nil
	}
	storedSig := raw[off : off+sigLen]
	mac := hmac.New(sha256.New, []byte(signerID))
	mac.Write(raw[:sigOff])
	expected := mac.Sum(nil)
	return hmac.Equal(expected, storedSig), nil
}

func validateProvenance(cf *types.CheckpointFile) bool {
	if cf.Provenance == nil {
		return false
	}
	p := cf.Provenance
	if p.Framework == "" {
		return false
	}
	if p.Epoch == 0 && p.GlobalStep == 0 {
		// allow zero, but ensure timestamp reasonable? spec says well-formed
	}
	if p.ParentHash != "" && len(p.ParentHash) != 64 {
		return false
	}
	return true
}
