func parseShardRecursive(path string) (logparser.ShardInfo, []types.TimelineEntry, error) {
	return logparser.ParseShard(path, filepath.Base(path))
}

func loadTimelineEntries(dir string) ([]types.TimelineEntry, []logparser.ShardInfo, error) {
	ap, err := DiscoverArtifacts(dir)
	if err != nil {
		return nil, nil, err
	}
	if len(ap.Logs) == 0 {
		return nil, nil, fmt.Errorf("no log shard files found")
	}
	var allEntries []types.TimelineEntry
	var shards []logparser.ShardInfo
	for _, p := range ap.Logs {
		info, entries, err := parseShardRecursive(p)
		if err != nil {
			continue
		}
		shards = append(shards, info)
		allEntries = append(allEntries, entries...)
	}
	if len(allEntries) == 0 {
		return nil, shards, fmt.Errorf("no log entries found")
	}
	return allEntries, shards, nil
}

func mergeTimeline(entries []types.TimelineEntry) ([]types.TimelineEntry, int) {
	type agg struct {
		entry   types.TimelineEntry
		sources map[string]struct{}
		conflict bool
	}
	m := map[string]*agg{}
	for _, e := range entries {
		key := fmt.Sprintf("%d:%d", e.Epoch, e.Step)
		a, ok := m[key]
		if !ok {
			src := map[string]struct{}{}
			for _, s := range e.Sources {
				src[s] = struct{}{}
			}
			m[key] = &agg{entry: e, sources: src}
			continue
		}
		for _, s := range e.Sources {
			a.sources[s] = struct{}{}
		}
		if metricsEqual(a.entry, e) {
			if e.Ts > a.entry.Ts {
				a.entry = e
			}
			continue
		}
		a.conflict = true
		if e.Ts > a.entry.Ts {
			a.entry = e
			}
	}
	result := make([]types.TimelineEntry, 0, len(m))
	conflicts := 0
	for _, a := range m {
		e := a.entry
		srcs := make([]string, 0, len(a.sources))
		for s := range a.sources {
			srcs = append(srcs, s)
		}
		sort.Strings(srcs)
		e.Sources = srcs
		e.Conflict = a.conflict
		if a.conflict {
			conflicts++
		}
		result = append(result, e)
	}
	return result, conflicts
}

func metricsEqual(a, b types.TimelineEntry) bool {
	return floatPtrEqual(a.Loss, b.Loss) &&
		floatPtrEqual(a.Lr, b.Lr) &&
		floatPtrEqual(a.GradNorm, b.GradNorm) &&
		floatPtrEqual(a.Acc, b.Acc)
}

func floatPtrEqual(a, b *float64) bool {
	if a == nil || b == nil {
		return a == b
	}
	return math.Abs(*a-*b) <= 1e-9
}

func sortTimeline(entries []types.TimelineEntry) {
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].Epoch != entries[j].Epoch {
			return entries[i].Epoch < entries[j].Epoch
		}
		return entries[i].Step < entries[j].Step
	})
}

func detectGaps(entries []types.TimelineEntry) []TimelineGap {
	var gaps []TimelineGap
	for i := 1; i < len(entries); i++ {
		prev := entries[i-1]
		cur := entries[i]
		if prev.Epoch != cur.Epoch {
			continue
		}
		diff := cur.Step - prev.Step
		if diff > 100 {
			gaps = append(gaps, TimelineGap{
				AfterStep:  prev.Step,
				BeforeStep: cur.Step,
				Epoch:      prev.Epoch,
				GapSteps:   diff,
				AfterTs:    prev.Ts,
				BeforeTs:   cur.Ts,
			})
		}
	}
	return gaps
}

