		Dataset   string `json:"dataset"`
	}
	if err := json.Unmarshal(raw, &cfg); err != nil {
		return IngestConfig{}, err
	}
	return IngestConfig{File: filepath.Base(path), ModelName: cfg.ModelName, Dataset: cfg.Dataset}, nil
}

