	}
	return buildLineage(cps), nil
}

func buildLineage(cps []*types.CheckpointFile) LineageOutput {
	out := LineageOutput{Status: "ok"}
	nodeByHash := map[string]*LineageNode{}
	cfByHash := map[string]*types.CheckpointFile{}

	for _, cf := range cps {
		cfByHash[cf.FileHash] = cf
		n := LineageNode{
			File:              cf.Filename,
			FileHash:          cf.FileHash,
			CreationTimestamp: unixToISO(cf.CreationTimestamp),
			ParentHash:        "",
		}
		if cf.Provenance != nil {
			n.Epoch = cf.Provenance.Epoch
			n.GlobalStep = cf.Provenance.GlobalStep
			n.ParentHash = cf.Provenance.ParentHash
		}
		nodeByHash[cf.FileHash] = &n
		out.Nodes = append(out.Nodes, *n)
	}

	children := map[string][]string{}
	incoming := map[string]int{}
	for _, cf := range cps {
		if cf.Provenance == nil || cf.Provenance.ParentHash == "" {
			continue
		}
		parent := cf.Provenance.ParentHash
		if _, ok := cfByHash[parent]; ok {
			children[parent] = append(children[parent], cf.FileHash)
			incoming[cf.FileHash]++
			out.Edges = append(out.Edges, LineageEdge{
				From:     parent,
				To:       cf.FileHash,
				FromFile: cfByHash[parent].Filename,
				ToFile:   cf.Filename,
			})
		}
	}

	for i := range out.Nodes {
		n := &out.Nodes[i]
		n.IsOrphan = n.ParentHash != "" && cfByHash[n.ParentHash] == nil
		n.IsRoot = n.ParentHash == "" && incoming[n.FileHash] == 0
		n.IsLeaf = len(children[n.FileHash]) == 0
		if n.IsRoot {
			out.Roots = append(out.Roots, n.FileHash)
		}
		if n.IsLeaf {
			out.Leaves = append(out.Leaves, n.FileHash)
		}
		if n.IsOrphan {
			out.Orphans = append(out.Orphans, n.FileHash)
		}
	}

	sort.Slice(out.Nodes, func(i, j int) bool {
		return out.Nodes[i].CreationTimestamp < out.Nodes[j].CreationTimestamp
	})
	sort.Slice(out.Edges, func(i, j int) bool {
		if out.Edges[i].From != out.Edges[j].From {
			return out.Edges[i].From < out.Edges[j].From
		}
		return out.Edges[i].To < out.Edges[j].To
	})
	sort.Strings(out.Roots)
	sort.Strings(out.Leaves)
	sort.Strings(out.Orphans)

	out.Cycles = detectCycles(nodeByHash, children)
	if len(out.Cycles) == 0 {
		out.TopologicalOrder = topoSort(nodeByHash, children, incoming)
	}

	if out.Nodes == nil {
		out.Nodes = []LineageNode{}
	}
	if out.Edges == nil {
		out.Edges = []LineageEdge{}
	}
	if out.Roots == nil {
		out.Roots = []string{}
	}
	if out.Leaves == nil {
		out.Leaves = []string{}
	}
	if out.Orphans == nil {
		out.Orphans = []string{}
	}
	if out.TopologicalOrder == nil {
		out.TopologicalOrder = []string{}
	}
	if out.Cycles == nil {
		out.Cycles = [][]string{}
	}
	return out
}

func detectCycles(nodeByHash map[string]*LineageNode, children map[string][]string) [][]string {
	const (
		white = 0
		gray  = 1
		black = 2
	)
	color := map[string]int{}
	stack := []string{}
	var cycles [][]string
	seen := map[string]bool{}

	var dfs func(u string)
	dfs = func(u string) {
		color[u] = gray
		stack = append(stack, u)
		for _, v := range children[u] {
			if color[v] == gray {
				for i := len(stack) - 1; i >= 0; i-- {
					if stack[i] == v {
						cycle := append([]string{}, stack[i:]...)
						sort.Strings(cycle)
						key := strings.Join(cycle, ",")
						if !seen[key] {
							seen[key] = true
							cycles = append(cycles, cycle)
						}
						break
					}
				}
			} else if color[v] == white {
				dfs(v)
			}
		}
		stack = stack[:len(stack)-1]
		color[u] = black
	}

	hashes := make([]string, 0, len(nodeByHash))
	for h := range nodeByHash {
		hashes = append(hashes, h)
	}
	sort.Strings(hashes)
	for _, h := range hashes {
		if color[h] == white {
			dfs(h)
		}
	}
	return cycles
}

func topoSort(nodeByHash map[string]*LineageNode, children map[string][]string, incoming map[string]int) []string {
	indeg := map[string]int{}
	for h, n := range nodeByHash {
		if n.IsOrphan {
			continue
		}
		indeg[h] = incoming[h]
	}

	var ready []string
	for h, n := range nodeByHash {
		if n.IsOrphan {
			continue
		}
		if indeg[h] == 0 {
			ready = append(ready, h)
		}
	}

	less := func(i, j int) bool {
		ti, _ := time.Parse(time.RFC3339, nodeByHash[ready[i]].CreationTimestamp)
		tj, _ := time.Parse(time.RFC3339, nodeByHash[ready[j]].CreationTimestamp)
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		return ready[i] < ready[j]
	}

	var order []string
	for len(ready) > 0 {
		sort.Slice(ready, less)
		cur := ready[0]
		ready = ready[1:]
		order = append(order, cur)
		for _, c := range children[cur] {
			if nodeByHash[c] == nil || nodeByHash[c].IsOrphan {
				continue
			}
			indeg[c]--
			if indeg[c] == 0 {
				ready = append(ready, c)
			}
		}
	}
	return order
}
