package forensics

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"mlforge/internal/types"
)

type QueryOutput struct {
	Status  string                 `json:"status"`
	Query   string                 `json:"query"`
	Matches int                    `json:"matches"`
	Entries []types.TimelineEntry   `json:"entries"`
}

func BuildQuery(dir, expr string) (interface{}, error) {
	entries, _, err := loadTimelineEntries(dir)
	if err != nil {
		return nil, err
	}
	merged, _ := mergeTimeline(entries)
	sortTimeline(merged)

	q, err := parseQuery(expr)
	if err != nil {
		return nil, err
	}
	var matches []types.TimelineEntry
	for _, e := range merged {
		if q.eval(e) {
			matches = append(matches, e)
		}
	}
	return QueryOutput{
		Status:  "ok",
		Query:   expr,
		Matches: len(matches),
		Entries: matches,
	}, nil
}

type condition struct {
	field string
	op    string
	sval  string
	fval  float64
	isNum bool
}

type orGroup struct {
	ands []condition
}

type query struct {
	ors []orGroup
}

func (q query) eval(e types.TimelineEntry) bool {
	for _, g := range q.ors {
		ok := true
		for _, c := range g.ands {
			if !c.eval(e) {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
	}
	return false
}

func (c condition) eval(e types.TimelineEntry) bool {
	switch c.field {
	case "step":
		return compareNum(float64(e.Step), c)
	case "epoch":
		return compareNum(float64(e.Epoch), c)
	case "loss":
		return ptrCompareNum(e.Loss, c)
	case "lr":
		return ptrCompareNum(e.Lr, c)
	case "grad_norm":
		return ptrCompareNum(e.GradNorm, c)
	case "acc":
		return ptrCompareNum(e.Acc, c)
	case "event":
		return compareStr(e.Event, c)
	case "ts":
		return compareTs(e.Ts, c)
	}
	return false
}

func compareNum(val float64, c condition) bool {
	if !c.isNum {
		return false
	}
	switch c.op {
	case ">":
		return val > c.fval
	case "<":
		return val < c.fval
	case ">=":
		return val >= c.fval
	case "<=":
		return val <= c.fval
	case "==":
		return absFloat(val-c.fval) <= 1e-9
	case "!=":
		return absFloat(val-c.fval) > 1e-9
	}
	return false
}

func ptrCompareNum(p *float64, c condition) bool {
	if p == nil {
		return false
	}
	return compareNum(*p, c)
}

func compareStr(val string, c condition) bool {
	if c.isNum {
		return false
	}
	switch c.op {
	case "==":
		return val == c.sval
	case "!=":
		return val != c.sval
	}
	return false
}

func compareTs(val string, c condition) bool {
	lt, err := time.Parse(time.RFC3339, val)
	if err != nil {
		return false
	}
	rt, err := time.Parse(time.RFC3339, c.sval)
	if err != nil {
		return false
	}
	switch c.op {
	case ">":
		return lt.After(rt)
	case "<":
		return lt.Before(rt)
	case ">=":
		return lt.After(rt) || lt.Equal(rt)
	case "<=":
		return lt.Before(rt) || lt.Equal(rt)
	case "==":
		return lt.Equal(rt)
	case "!=":
		return !lt.Equal(rt)
	}
	return false
}

func absFloat(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

func parseQuery(expr string) (query, error) {
	tokens, err := tokenizeQuery(expr)
	if err != nil {
		return query{}, err
	}
	var q query
	var cur orGroup
	i := 0
	for i < len(tokens) {
		tok := tokens[i]
		if tok == "AND" || tok == "OR" {
			if tok == "OR" {
				q.ors = append(q.ors, cur)
				cur = orGroup{}
			} else if tok == "AND" {
				// continue adding to cur
			}
			i++
			continue
		}
		cond, next, err := parseCondition(tokens, i)
		if err != nil {
			return query{}, err
		}
		cur.ands = append(cur.ands, cond)
		i = next
	}
	if len(cur.ands) > 0 || len(q.ors) == 0 {
		q.ors = append(q.ors, cur)
	}
	if len(q.ors) == 0 || len(q.ors[0].ands) == 0 {
		return query{}, fmt.Errorf("empty query")
	}
	return q, nil
}

func parseCondition(tokens []string, i int) (condition, int, error) {
	if i+2 >= len(tokens) {
		return condition{}, i, fmt.Errorf("invalid query syntax")
	}
	field := tokens[i]
	op := tokens[i+1]
	valueTok := tokens[i+2]

	validFields := map[string]bool{"step": true, "epoch": true, "loss": true, "lr": true, "grad_norm": true, "acc": true, "event": true, "ts": true}
	if !validFields[field] {
		return condition{}, i, fmt.Errorf("unknown field: %s", field)
	}
	validOps := map[string]bool{">": true, "<": true, ">=": true, "<=": true, "==": true, "!=": true}
	if !validOps[op] {
		return condition{}, i, fmt.Errorf("invalid operator: %s", op)
	}

	c := condition{field: field, op: op, sval: valueTok}
	if field == "event" {
		if op != "==" && op != "!=" {
			return condition{}, i, fmt.Errorf("type mismatch: event only supports == or !=")
		}
		if !isQuotedString(valueTok) {
			return condition{}, i, fmt.Errorf("type mismatch: event requires string value")
		}
		c.sval = unquote(valueTok)
		return c, i + 3, nil
	}
	if field == "ts" {
		if _, err := time.Parse(time.RFC3339, unquote(valueTok)); err != nil {
			return condition{}, i, fmt.Errorf("invalid timestamp: %s", valueTok)
		}
		c.sval = unquote(valueTok)
		return c, i + 3, nil
	}
	num, err := strconv.ParseFloat(valueTok, 64)
	if err != nil {
		return condition{}, i, fmt.Errorf("type mismatch: %s requires numeric value", field)
	}
	c.fval = num
	c.isNum = true
	return c, i + 3, nil
}

func tokenizeQuery(s string) ([]string, error) {
	var tokens []string
	i := 0
	for i < len(s) {
		ch := s[i]
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			i++
			continue
		}
		if ch == '"' {
			j := i + 1
			for j < len(s) && s[j] != '"' {
				j++
			}
			if j >= len(s) {
				return nil, fmt.Errorf("unterminated string")
			}
			tokens = append(tokens, s[i:j+1])
			i = j + 1
			continue
		}
		if strings.HasPrefix(s[i:], ">=") || strings.HasPrefix(s[i:], "<=") || strings.HasPrefix(s[i:], "==") || strings.HasPrefix(s[i:], "!=") {
			tokens = append(tokens, s[i:i+2])
			i += 2
			continue
		}
		if ch == '>' || ch == '<' {
			tokens = append(tokens, string(ch))
			i++
			continue
		}
		j := i
		for j < len(s) {
			c := s[j]
			if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '>' || c == '<' || c == '=' || c == '!' || c == '"' {
				break
			}
			j++
		}
		if j == i {
			return nil, fmt.Errorf("invalid character in query: %c", ch)
		}
		tokens = append(tokens, s[i:j])
		i = j
	}
	return tokens, nil
}

func isQuotedString(s string) bool {
	return len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"'
}

func unquote(s string) string {
	if isQuotedString(s) {
		return s[1 : len(s)-1]
	}
	return s
}
