package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"mlforge/internal/forensics"
)

func main() {
	// --- Parse flags ---------------------------------------------------
	format := "json"
	verbose := false
	var positional []string

	for _, arg := range os.Args[1:] {
		switch {
		case arg == "--verbose":
			verbose = true
		case strings.HasPrefix(arg, "--format="):
			format = strings.TrimPrefix(arg, "--format=")
		case arg == "--format":
			// handled below as two-token flag
		default:
			positional = append(positional, arg)
		}
	}

	// Handle "--format json" (two separate tokens)
	for i := 1; i < len(os.Args)-1; i++ {
		if os.Args[i] == "--format" {
			format = os.Args[i+1]
			// Remove the value from positional args
			filtered := positional[:0]
			for _, p := range positional {
				if p != os.Args[i+1] {
					filtered = append(filtered, p)
				}
			}
			positional = filtered
			break
		}
	}

	if format != "json" && format != "text" {
		fmt.Fprintf(os.Stderr, "invalid format %q: must be json or text\n", format)
		os.Exit(1)
	}

	_ = verbose // reserved for diagnostic output

	// --- Validate positional args --------------------------------------
	if len(positional) < 2 {
		fmt.Fprintf(os.Stderr, "Usage: mlforge <command> <evidence-dir> [args...]\n")
		os.Exit(1)
	}

	cmd := positional[0]
	dir := positional[1]

	// --- Route to command handler --------------------------------------
	var result interface{}
	var err error

	switch cmd {
	case "ingest":
		result, err = forensics.BuildIngest(dir)
	case "timeline":
		result, err = forensics.BuildTimeline(dir)
	case "verify":
		result, err = forensics.BuildVerify(dir)
	case "detect":
		result, err = forensics.BuildDetect(dir)
	case "lineage":
		result, err = forensics.BuildLineage(dir)
	case "query":
		if len(positional) < 3 {
			fmt.Fprintf(os.Stderr, "Usage: mlforge query <dir> \"<expression>\"\n")
			os.Exit(1)
		}
		result, err = forensics.BuildQuery(dir, positional[2])
	case "report":
		result, err = forensics.BuildReport(dir)
	default:
		fmt.Fprintf(os.Stderr, "unknown command: %s\n", cmd)
		os.Exit(1)
	}

	// --- Output --------------------------------------------------------
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	if format == "text" {
		printText(result)
		return
	}

	out, marshalErr := json.MarshalIndent(result, "", "  ")
	if marshalErr != nil {
		fmt.Fprintf(os.Stderr, "error marshalling result: %v\n", marshalErr)
		os.Exit(1)
	}
	fmt.Println(string(out))
}

func printText(v interface{}) {
	b, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		fmt.Fprintln(os.Stderr, "error rendering text output")
		return
	}
	fmt.Println(string(b))
}
